params.command:
$ErrorActionPreference='Stop'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
Set-Location $repo
git fetch origin --prune
if($LASTEXITCODE -ne 0){ throw 'git fetch failed' }

$active=@()
$wtLines=@(git worktree list --porcelain)
foreach($line in $wtLines){
  if($line -like 'branch refs/heads/*'){ $active += $line.Substring(18) }
}

$protected=@('main','heaven-bridge')
$deleted=@()
$skipped=@()
$errors=@()

$refs=@(git for-each-ref --format='%(refname:short)' refs/remotes/origin |
  Where-Object { $_ -ne 'origin/HEAD' -and $_ -like 'origin/*' } |
  ForEach-Object { $_.Substring(7) } |
  Sort-Object -Unique)

foreach($b in $refs){
  if($b -in $protected){ continue }
  if($b -in $active){
    $skipped += [ordered]@{branch=$b;reason='active-worktree'}
    continue
  }

  $safe=$false
  $proof=$null

  git merge-base --is-ancestor "origin/$b" origin/main 2>$null
  if($LASTEXITCODE -eq 0){
    $safe=$true
    $proof='ancestor-of-main'
  } else {
    $cherry=@(git cherry origin/main "origin/$b" 2>$null)
    if($LASTEXITCODE -eq 0){
      $unique=@($cherry | Where-Object { $_ -match '^\+' })
      if($unique.Count -eq 0){
        $safe=$true
        $proof='no-unique-patches-vs-main'
      }
    }
  }

  if($safe){
    git push origin --delete $b
    if($LASTEXITCODE -eq 0){
      $deleted += [ordered]@{branch=$b;proof=$proof}
    } else {
      $errors += [ordered]@{branch=$b;reason='remote-delete-failed'}
    }
  } else {
    $skipped += [ordered]@{branch=$b;reason='unique-work-remains'}
  }
}

git fetch origin --prune | Out-Null
$remaining=@(git for-each-ref --format='%(refname:short)' refs/remotes/origin |
  Where-Object { $_ -ne 'origin/HEAD' -and $_ -like 'origin/*' } |
  ForEach-Object { $_.Substring(7) } |
  Sort-Object -Unique)

[ordered]@{
  main=(git rev-parse origin/main | Out-String).Trim()
  deleted_count=$deleted.Count
  deleted=$deleted
  skipped_count=$skipped.Count
  skipped=$skipped
  errors=$errors
  remaining_count=$remaining.Count
  remaining=$remaining
  active_worktrees=$active
} | ConvertTo-Json -Depth 6
